update expert_profile
set service_status = #{status}, version = version + 1, update_time = sysdate()
where user_id = #{userId}
  and service_status = #{sourceStatus}
  and del_flag = '0'

update expert_unavailable_period
set start_time = #{startTime},
    end_time = #{endTime},
    reason = #{reason},
    version = version + 1,
    update_by = #{updateBy},
    update_time = sysdate()
where unavailable_id = #{unavailableId}
  and user_id = #{userId}
  and version = #{version}

